SELECT

FROM swm_beacon_station a
LEFT JOIN swm_site_map_management building_node
    ON building_node.id = a.building_id

        AND building_node.corp_code = #{corpCode}

LEFT JOIN swm_site_map_management floor_node
    ON floor_node.id = a.floor_id

        AND floor_node.corp_code = #{corpCode}

WHERE a.id = #{id}

    AND a.corp_code = #{corpCode}

SELECT

FROM swm_beacon_station a
LEFT JOIN swm_site_map_management building_node
    ON building_node.id = a.building_id

        AND building_node.corp_code = #{corpCode}

LEFT JOIN swm_site_map_management floor_node
    ON floor_node.id = a.floor_id

        AND floor_node.corp_code = #{corpCode}


    a.status = '0'

        AND a.corp_code = #{corpCode}


        AND a.beacon_id LIKE CONCAT('%', #{beaconId}, '%')


        AND a.device_name LIKE CONCAT('%', #{deviceName}, '%')


        AND a.beacon_type = #{beaconType}


        AND a.location LIKE CONCAT('%', #{location}, '%')


        AND a.area LIKE CONCAT('%', #{area}, '%')


        AND a.beacon_status = #{beaconStatus}


        AND a.deploy_status = #{deployStatus}


        AND a.building_id = #{buildingId}


        AND building_node.map_name LIKE CONCAT('%', #{building}, '%')


        AND a.floor_id = #{floorId}


ORDER BY ${sqlMap.order.toSql()}

SELECT COUNT(1)
FROM swm_beacon_station a
WHERE a.beacon_id = #{beaconId}
AND a.status = '0' 

    AND a.id != #{id}

SELECT 
    *
FROM swm_beacon_station a
WHERE a.status = '0' 

    AND a.gps_longitude >= #{minLongitude}


    AND a.gps_longitude <= #{maxLongitude}


    AND a.gps_latitude >= #{minLatitude}


    AND a.gps_latitude <= #{maxLatitude}

ORDER BY a.update_date DESC

SELECT 
    *
FROM swm_beacon_station a
WHERE a.status = '0' 

    AND a.pixel_x >= #{minX}


    AND a.pixel_x <= #{maxX}


    AND a.pixel_y >= #{minY}


    AND a.pixel_y <= #{maxY}

ORDER BY a.update_date DESC

